function validate([lane1, lane2]) {
  if (lane1.length < 1 || lane1.length > 100000) return 'lane1 needs 1 to 10^5 values.';
  if (lane2.length !== lane1.length) return 'lane1 and lane2 must have the same length.';
  if (lane1.some(v => v < -1e9 || v > 1e9) || lane2.some(v => v < -1e9 || v > 1e9)) return 'Each value is between -10^9 and 10^9.';
  return null;
}

