function maxCoins(lane1, lane2) {
  // Best total of a drive that ends at the current mile after 0, 1 or 2 switches.
  let noSwitch = -Infinity;
  let oneSwitch = -Infinity;
  let twoSwitches = -Infinity;
  let best = -Infinity;
  for (let i = 0; i < lane1.length; i++) {
    // Update the last state first, so each state still reads the previous mile's values.
    twoSwitches = Math.max(twoSwitches, oneSwitch) + lane1[i];
    oneSwitch = Math.max(oneSwitch, noSwitch, 0) + lane2[i];
    noSwitch = Math.max(noSwitch, 0) + lane1[i];
    best = Math.max(best, noSwitch, oneSwitch, twoSwitches);
  }
  return best;
}

