function maxCoins(lane1, lane2) {
  // Try every run of miles and every lane for each of its miles, keeping the choices with at most
  // two switches; getting on in lane 2 already counts as one switch.
  const n = lane1.length;
  let best = -Infinity;
  for (let start = 0; start < n; start++)
    for (let end = start; end < n; end++) {
      const length = end - start + 1;
      for (let mask = 0; mask < 1 << length; mask++) {
        let lane = 1, switches = 0, total = 0;
        for (let k = 0; k < length; k++) {
          const here = (mask >> k) & 1 ? 2 : 1;
          if (here !== lane) { switches++; lane = here; }
          total += here === 1 ? lane1[start + k] : lane2[start + k];
        }
        if (switches <= 2) best = Math.max(best, total);
      }
    }
  return best;
}

