function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 2000 : 1 + pick(8);
  // Small ranges make ties common; now and then the full range of values is used.
  const span = size === 'large' || rand() < 0.2 ? 1e9 : [3, 10, 100][pick(3)];
  // Lean the values negative, positive or neither, so roads full of tolls and full of coins both appear.
  const third = Math.floor(span / 3);
  const [low, high] = [[-span, span], [-span, span], [-span, third], [-third, span], [-span, -1], [0, span]][pick(6)];
  const value = () => low + pick(high - low + 1);
  return [Array.from({ length: n }, value), Array.from({ length: n }, value)];
}
